/**
 * Normaliza filas_excel → 1 item con {_rows, _n}.
 * Acepta array, string JSON, objeto envuelto, markdown fences.
 */
function stripFences(s) {
  return String(s).trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();
}

function tryParse(s) {
  try { return JSON.parse(s); } catch (e) { return null; }
}

function normalizeFilas(raw) {
  if (raw == null || raw === '') return [];

  if (typeof raw === 'string') {
    const parsed = tryParse(stripFences(raw));
    if (parsed == null) return [];
    raw = parsed;
  }

  if (Array.isArray(raw) && raw.length === 1 && typeof raw[0] === 'string') {
    const parsed = tryParse(stripFences(raw[0]));
    if (parsed != null) raw = parsed;
  }

  if (raw && typeof raw === 'object' && !Array.isArray(raw)) {
    if (Array.isArray(raw.filas_excel)) raw = raw.filas_excel;
    else if (Array.isArray(raw.data)) raw = raw.data;
    else if (Array.isArray(raw.rows)) raw = raw.rows;
    else if (Array.isArray(raw.datos)) raw = raw.datos;
    else raw = [raw];
  }

  if (!Array.isArray(raw)) return [];

  const rows = [];
  for (const item of raw) {
    let row = item;
    if (typeof row === 'string') {
      const parsed = tryParse(stripFences(row));
      if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) row = parsed;
      else continue;
    }
    if (!row || typeof row !== 'object' || Array.isArray(row)) continue;

    const out = {};
    for (const [k, v] of Object.entries(row)) {
      if (v === null || v === undefined) out[k] = '';
      else if (typeof v === 'object') out[k] = JSON.stringify(v);
      else out[k] = v;
    }
    if (Object.keys(out).length) rows.push(out);
  }
  return rows;
}

const trigger = $input.first().json;
const raw = trigger.filas_excel !== undefined ? trigger.filas_excel : trigger;
let rows = normalizeFilas(raw);

if (!rows.length) {
  throw new Error(
    'filas_excel inválido o vacío. Se esperaba un Array JSON de objetos homogéneos. ' +
    'Ejemplo: [{"Fecha_Hora":"24/07 12:00","Temperatura_C":22,"Viento_kt":12}]'
  );
}

const keys = [];
const seen = new Set();
for (const r of rows) {
  for (const k of Object.keys(r)) {
    if (!seen.has(k)) { seen.add(k); keys.push(k); }
  }
}
rows = rows.map((r) => {
  const o = {};
  for (const k of keys) o[k] = r[k] !== undefined ? r[k] : '';
  return o;
});

return [{ json: { _rows: rows, _n: rows.length, _keys: keys } }];

const id = $('Create sheet').first().json.spreadsheetId;
const n = $('Normalizar filas').first().json._n || 0;
const url = 'https://docs.google.com/spreadsheets/d/' + id + '/edit';
return [{
  json: {
    mensaje_respuesta: '[Abrir planilla Excel](' + url + ')',
    url_planilla: url,
    filas_escritas: n
  }
}];
